mapper.select:
SELECT hazard_point_id
FROM alarm_strategy_hazard_point
WHERE strategy_id = #{strategyId}

mapper.delete:
DELETE
FROM alarm_strategy_hazard_point
WHERE strategy_id = #{strategyId}
  AND hazard_point_id = #{hazardPointId}

mapper.select:
SELECT COUNT(*)
FROM alarm_strategy_hazard_point
WHERE strategy_id = #{strategyId}
